import type { LlmsTxtOptions } from './types.js';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { generateLlmsTxtContent, type PageInfo } from './formatter.js';
import { processAllFiles, type ProcessorLogger } from './processor.js';
import { chunkContent, formatChunkWithMetadata } from './chunker.js';
import { generateMcpManifests, createMcpSseHandler } from './mcp.js';
import { resetProviderFailures } from './aiProvider.js';
import { fetchFromDataStore } from './datastore.js';
import { lintGEO } from './geo-linter.js';
import { findHtmlFiles } from './utils.js';

interface AstroLogger {
  info: (...args: unknown[]) => void;
  warn: (...args: unknown[]) => void;
  error: (...args: unknown[]) => void;
  debug: (...args: unknown[]) => void;
}

interface AstroConfigLike {
  root: URL;
  site?: string;
}

interface AstroDevServer {
  middlewares: {
    use: (
      path: string,
      handler: (req: unknown, res: unknown, next: (err?: unknown) => void) => void
    ) => void;
  };
}

/**
 * Astro Integration: llms.txt Generator
 *
 * This plugin generates an LLM-optimized llms.txt in the build output for every Astro build.
 * Compatible with Astro 5.x, 6.x, and 7.x+.
 * @param options - Plugin configuration.
 * @returns Integration object with build hook.
 */
export default function llmsTxt(options: LlmsTxtOptions = {}) {
  // Mutable state shared between hooks inside the closure
  let projectRoot = process.cwd();
  let astroSiteUrl = '';
  const cachedPages: PageInfo[] = [];

  function writeLlmsTxt(distPath: string, content: string, logger: AstroLogger): void {
    const outPath = path.join(distPath, 'llms.txt');
    fs.writeFileSync(outPath, content, { encoding: 'utf8' });
    logger.info(`Generated llms.txt at ${outPath}`);
  }

  return {
    name: 'llms-txt',
    hooks: {
      // Capture the project root and Astro site config early
      'astro:config:done': ({ config }: { config: AstroConfigLike }) => {
        projectRoot = fileURLToPath(config.root);
        if (config.site) {
          astroSiteUrl = config.site;
        }
      },

      // Register local MCP SSE server during `astro dev`
      'astro:server:setup': ({ server }: { server: AstroDevServer }) => {
        if (!options.mcp) return;
        const mcpOpts = typeof options.mcp === 'object' ? options.mcp : {};
        if (mcpOpts.devServer === false) return;
        const serverPath = mcpOpts.serverPath ?? '/__mcp/sse';
        server.middlewares.use(serverPath, (req, res, next) => {
          try {
            createMcpSseHandler(() => [...cachedPages])(req, res);
          } catch (e) {
            next(e);
          }
        });
      },

      'astro:build:done': async ({ dir, logger }: { dir: URL; logger: AstroLogger }) => {
        resetProviderFailures();
        const distPath = fileURLToPath(dir);
        const resolvedDistPath = path.resolve(distPath);
        const effectiveOptions: LlmsTxtOptions = {
          ...options,
          site: options.site || astroSiteUrl || '',
        };
        const contentSource = effectiveOptions.contentSource ?? 'html';

        let validPages: PageInfo[] = [];

        // 1. Optional DataStore extraction ('datastore' or 'auto')
        if (
          (contentSource === 'datastore' || contentSource === 'auto') &&
          effectiveOptions.dataStore
        ) {
          const resolvedStore =
            typeof effectiveOptions.dataStore === 'function'
              ? await effectiveOptions.dataStore()
              : effectiveOptions.dataStore;
          const storePages = fetchFromDataStore(resolvedStore, effectiveOptions).filter(
            (p) => p.summary.length > 0 || (p.fullContent && p.fullContent.length > 0)
          );
          if (storePages.length > 0 || contentSource === 'datastore') {
            validPages = storePages;
            if (effectiveOptions.geoLinter !== false && validPages.length > 0) {
              lintGEO(validPages, logger);
            }
          }
        }

        // 2. HTML Extraction (when 'html', or 'auto' fallback when DataStore yielded no pages)
        if (contentSource === 'html' || (contentSource === 'auto' && validPages.length === 0)) {
          const htmlFiles = await findHtmlFiles(resolvedDistPath);

          if (!htmlFiles.length) {
            logger.warn('No HTML files found. Skipping llms.txt generation.');
            const { short } = generateLlmsTxtContent([], effectiveOptions);
            writeLlmsTxt(distPath, short, logger);
            return;
          }

          // Setup Cache
          const cacheDir = path.join(resolvedDistPath, '.llms-txt-cache');
          if (!fs.existsSync(cacheDir)) {
            fs.mkdirSync(cacheDir, { recursive: true });
          }

          // Process Files (Extract & AI Summarize; GEO linter runs inside processAllFiles)
          const processorLogger: ProcessorLogger = logger;
          validPages = await processAllFiles(
            htmlFiles,
            resolvedDistPath,
            effectiveOptions,
            processorLogger,
            cacheDir
          );
        }

        if (!validPages.length) {
          logger.warn('No valid summaries generated. Writing an empty llms.txt header.');
        }

        // Cache pages for the MCP SSE server (used in dev mode)
        cachedPages.splice(0, cachedPages.length, ...validPages);

        // 3. Generate Content (Format)
        const { short, full } = generateLlmsTxtContent(validPages, effectiveOptions);

        // 4. Write Files
        writeLlmsTxt(distPath, short, logger);

        if (full && effectiveOptions.llmsFull) {
          const fullOutPath = path.join(distPath, 'llms-full.txt');
          fs.writeFileSync(fullOutPath, full, { encoding: 'utf8' });
          logger.info(`Generated llms-full.txt at ${fullOutPath}`);
        }

        // 5. Chunked export (optional)
        const chunkStrategy = effectiveOptions.chunking?.strategy;
        if (chunkStrategy && chunkStrategy !== 'none' && effectiveOptions.chunkExport === 'jsonl') {
          const pagesWithContent = validPages.filter((p) => p.fullContent);
          const chunkArrays = await Promise.all(
            pagesWithContent.map((page) =>
              chunkContent(page.fullContent!, page.title, page.relUrl, effectiveOptions.chunking)
            )
          );
          const allChunks = chunkArrays
            .flat()
            .map((chunk) =>
              JSON.stringify({ ...chunk, formatted: formatChunkWithMetadata(chunk) })
            );
          if (allChunks.length > 0) {
            const jsonlPath = path.join(distPath, 'llms-chunks.jsonl');
            fs.writeFileSync(jsonlPath, allChunks.join('\n'), { encoding: 'utf8' });
            logger.info(`Generated llms-chunks.jsonl (${allChunks.length} chunks) at ${jsonlPath}`);
          }
        }

        // 6. MCP manifests
        if (effectiveOptions.mcp) {
          const mcpOpts = typeof effectiveOptions.mcp === 'object' ? effectiveOptions.mcp : {};
          if (mcpOpts.manifests !== false) {
            generateMcpManifests(projectRoot, {
              siteUrl: effectiveOptions.site!,
              serverPath: mcpOpts.serverPath,
              port: mcpOpts.port,
              llmsFullPath: effectiveOptions.llmsFull ? 'llms-full.txt' : undefined,
            });
            logger.info('Generated MCP manifests (.cursor/mcp.json, .vscode/mcp.json, .mcp.json)');
          }
        }
      },
    },
  };
}
